// ─── File: InnerClassDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.inner;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class InnerClassDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));

        Branch branch = new Branch("Mumbai-Main");
        branch.register(rajesh);
        branch.register(priya);

        // STATIC NESTED CLASS: TransferResult returned by value, no outer ref.
        Branch.TransferResult result = branch.transfer("SAV2001", "CUR3001",
                new BigDecimal("50000"),
                // ANONYMOUS CLASS implementing the listener on the spot.
                new TransferListener() {
                    @Override public void completed(String transferId, BigDecimal amount) {
                        log.info(() -> "callback: transfer " + transferId + " of Rs." + amount + " done");
                    }
                });
        log.info(() -> "Result id=" + result.transferId() + " rajesh=Rs." + result.fromBalance()
                + " priya=Rs." + result.toBalance());

        // NON-STATIC MEMBER CLASS: created through an outer instance.
        Branch.LedgerAuditor auditor = branch.new LedgerAuditor();
        auditor.verifyTotals();
    }
}

// ─── Would be in TransferListener.java (single-method interface) ───
interface TransferListener {
    void completed(String transferId, BigDecimal amount);
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
}

// ─── Would be in Branch.java (OUTER class holding all four inner forms) ───
class Branch {
    private static final Logger log = Logger.getLogger("BankLog");
    private final String branchName;
    private final java.util.Map<String, Account> ledger = new java.util.HashMap<>();
    private int transferSeq = 0;

    Branch(String branchName) { this.branchName = branchName; }
    void register(Account a) { ledger.put(a.getAccountId(), a); }

    // STATIC NESTED CLASS: a pure data carrier, no reference to a Branch instance.
    static class TransferResult {
        private final String transferId;
        private final BigDecimal fromBalance;
        private final BigDecimal toBalance;
        TransferResult(String id, BigDecimal from, BigDecimal to) {
            this.transferId = id; this.fromBalance = from; this.toBalance = to;
        }
        String transferId() { return transferId; }
        BigDecimal fromBalance() { return fromBalance; }
        BigDecimal toBalance() { return toBalance; }
    }

    TransferResult transfer(String fromId, String toId, BigDecimal amount, TransferListener listener) {
        Account from = ledger.get(fromId);
        Account to = ledger.get(toId);
        from.debit(amount);
        to.credit(amount);
        String id = branchName + "-TXF-" + (++transferSeq);
        listener.completed(id, amount);   // fire the anonymous-class callback
        return new TransferResult(id, from.getBalance(), to.getBalance());
    }

    // NON-STATIC MEMBER (INNER) CLASS: holds implicit reference to this Branch,
    // so it can read the enclosing branch's private ledger directly.
    class LedgerAuditor {
        void verifyTotals() {
            // LOCAL CLASS declared inside a method, visible only here.
            class LineFormatter {
                String format(Account a) {
                    return a.getAccountId() + "(" + a.getHolderName() + ")=Rs." + a.getBalance();
                }
            }
            LineFormatter fmt = new LineFormatter();
            BigDecimal sum = BigDecimal.ZERO;
            for (Account a : ledger.values()) {         // direct access to OUTER field
                log.fine(() -> "audit line " + fmt.format(a));
                sum = sum.add(a.getBalance());
            }
            BigDecimal finalSum = sum;
            log.info(() -> "Branch " + branchName + " total across ledger = Rs." + finalSum);
        }
    }
}
